REGISTER = re.compile(r"r(?:[0-9]|[12][0-9]|3[01])\Z")
def parse_register(text):
    return int(text[1:]) if REGISTER.fullmatch(text) else None
def read_inputs():
    trace = Path("input/trace.txt").read_text(encoding="ascii").splitlines()
    config = {"predictors": [], "variants": []}
    for line in Path("input/config.txt").read_text(encoding="ascii").splitlines():
        key, *values = line.split(" ")
        elif key == "VARIANT":
            config["variants"].append({"name": values[0], "forwarding": values[1] == "ON",
                                       "stage": values[2], "latency": int(values[3])})
        elif key == "PRIMARY":
            config["primary"] = tuple(values)
        elif key == "WINDOW":
            config["window"] = tuple(map(int, values))
def dependencies(instructions):
    last_writer = {}
    sources = []
    for index, instruction in enumerate(instructions):
        current = []
        for field in ("rs1", "rs2"):
            register = instruction[field]
            if register is not None and register != 0:
                current.append({"field": field, "register": register,
                                "producer": last_writer.get(register)})
        sources.append(current)
        destination = instruction["rd"]
        if destination is not None and destination != 0:
            last_writer[destination] = index
    return sources
def id_resolved(instruction, variant):
    if instruction["class"] == "JUMP" and instruction["rs1"] is None:
        return True
    return instruction["class"] in ("BRANCH", "JUMP") and variant["stage"] == "ID"


def ready_cycle(instruction, producer, producer_time, variant):
    if not variant["forwarding"]:
        return producer_time["W"] + 1
    result = producer_time["W"] if producer["class"] == "LOAD" else producer_time["M"]
    return result + int(id_resolved(instruction, variant))
CAUSES = ("control", "structural", "load_use", "raw")
STAGES = ("IF", "ID", "EX", "MEM", "WB")
def simulate(instructions, sources, variant, mispredicted):
    timings = []
    records = []
    delays = []
    for index, instruction in enumerate(instructions):
        execute = variant["latency"] if instruction["class"] == "MUL" else 1
        if index == 0:
            fetch, decode, start = 1, 2, 3
        else:
            previous = timings[-1]
            if mispredicted[index - 1]:
                fetch = previous["X"] + int(not id_resolved(instructions[index - 1], variant))
            else:
                fetch = previous["D"]
            decode = max(fetch + 1, previous["X"])
            ideal = previous["X"] + 1
            load_ready = ideal
            raw_ready = ideal
            load_producer = None
            raw_producer = None
            for source in sources[index]:
                producer = source["producer"]
                if producer is None:
                    continue
                ready = ready_cycle(instruction, instructions[producer], timings[producer], variant)
                if instructions[producer]["class"] == "LOAD":
                    if ready > load_ready:
                        load_ready, load_producer = ready, producer
                elif ready > raw_ready:
                    raw_ready, raw_producer = ready, producer
            bounds = (decode + 1, previous["M"], load_ready, raw_ready)
            start = ideal
            for cause, bound, producer in zip(CAUSES, bounds, (None, None, load_producer, raw_producer)):
                if bound > start:
                    records.append({"cause": cause, "cycles": bound - start,
                                    "responsible": index - 1 if cause in ("control", "structural") else index,
                                    "waiting": index, "producer": producer})
                    start = bound
            delays.append(start - ideal)
        timings.append({"F": fetch, "D": decode, "X": start,
                        "M": start + execute, "W": start + execute + 1})
    return {"timings": timings, "records": records, "delays": delays, "cycles": timings[-1]["W"]}
